UPDATE materials SET full_text=full_text||'صور أبشة ووداي — الدفعة الثالثة: كتاب برويل (1918)
المصدر: Georges Bruel, L’Afrique Équatoriale Française : le pays, les habitants, la colonisation, les pouvoirs publics (باريس: E. Larose، 1918) — رقمنة المكتبة العامة في نيويورك NYPL (ملك عام). المصوّر: الملازم فيراندي (Cliché du Lieut. Ferrandi). التاريخ الموثق: سنة النشر 1918؛ الالتقاط الفعلي نحو 1909–1913.
1) صور محمّلة (4)
الملف: bruel-tata-interieur-abeche-1918.jpg
الموضوع: داخل التاتا (سور قصر السلطان) في أبشة — جندي تيرايور على السور
—
الملف: bruel-grande-place-abeche-1918.jpg
الموضوع: الساحة الكبرى في أبشة — حشد ضخم يوم السوق
—
الملف: bruel-ville-vue-poste-abeche-1918.jpg
الموضوع: مدينة أبشة من البوست الفرنسي — وفي الخلف جناح السلطان علي المبني بالآجر
—
الملف: bruel-gaourang-doudmourrah-1918.jpg
الموضوع: سلطان وداي دودمورا (1902–1909) مع سلطان باقرمي غاورانغ
—
الأرشيف: NYPL Digital Collections (كتاب برويل 1918). التقرير الكامل مع الروابط في reports/images-abeche-ouaddai.md.
2) خيوط موثقة غير قابلة للتحميل حاليًا
• «Le Kolak Acyl sur son rifaï» — السلطان أصيل على حماره (صورة مختلفة عن لوح MUNAE) — NYPL Image ID 1267433.
• «Ville de Chokkoyan, pays Abou Charib (Ouadaï)» — مدينة شوكويان بوداي — NYPL Image ID 1267430.
• متحف Matheysin: نحو 20 صورة من العشرينيات غير مرقمنة — تتطلب مراسلة أو زيارة.' WHERE ark='ARC-TD-DOC-000007';
